<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxConfirmDialog from'../../components/ui/NxConfirmDialog.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{createRadiusSetting,deleteRadiusSetting,getRadiusSetting,listRadiusSettings,updateRadiusSetting}from'./api';import type{RadiusPayload,RadiusSetting}from'./contracts';
const rows=ref<RadiusSetting[]>([]),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),modalError=ref(''),modalOpen=ref(false),editing=ref<RadiusSetting|null>(null),pendingDelete=ref<RadiusSetting|null>(null);const form=reactive<RadiusPayload>({host:'',db_name:'',db_user:'',db_password:'',is_active:1});
const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return rows.value.filter(row=>!q||`${row.host} ${row.db_name} ${row.db_user}`.toLowerCase().includes(q));});const activeCount=computed(()=>rows.value.filter(row=>Boolean(Number(row.is_active))).length);
function clear(){error.value='';notice.value='';modalError.value='';}function fmt(value?:string){if(!value)return'—';const date=new Date(value.replace(' ','T'));return Number.isNaN(date.valueOf())?value:date.toLocaleString();}async function load(showNotice=false){loading.value=true;clear();try{rows.value=await listRadiusSettings();if(showNotice)notice.value='RADIUS servers refreshed.';}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to load RADIUS settings.';}finally{loading.value=false;}}
function openNew(){clear();editing.value=null;Object.assign(form,{host:'',db_name:'',db_user:'',db_password:'',is_active:1});modalOpen.value=true;}async function openEdit(row:RadiusSetting){clear();try{const fresh=await getRadiusSetting(row.id);editing.value=fresh;Object.assign(form,{host:fresh.host||'',db_name:fresh.db_name||'',db_user:fresh.db_user||'',db_password:'',is_active:Number(fresh.is_active)?1:0});modalOpen.value=true;}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to load RADIUS settings.';}}
async function submit(){modalError.value='';if(!form.host.trim()||!form.db_name.trim()||!form.db_user.trim()||(!editing.value&&!form.db_password)){modalError.value='Host, database name, username, and a password for new servers are required.';return;}saving.value=true;try{const result=editing.value?await updateRadiusSetting(editing.value.id,{...form}):await createRadiusSetting({...form});modalOpen.value=false;await load(false);notice.value=result.message||'RADIUS settings saved.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Unable to save RADIUS settings.';}finally{saving.value=false;}}
async function executeDelete(){if(!pendingDelete.value)return;saving.value=true;modalError.value='';try{const result=await deleteRadiusSetting(pendingDelete.value.id);pendingDelete.value=null;await load(false);notice.value=result.message||'RADIUS settings deleted.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Unable to delete RADIUS settings.';}finally{saving.value=false;}}onMounted(()=>void load());
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Access and authentication infrastructure" title="RADIUS Management" description="Register database endpoints used by subscriber authentication, authorization, and accounting."><template #actions><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton @click="openNew">Add Server</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-3"><NxCard><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Registered servers</p><p class="mt-2 text-2xl font-bold">{{rows.length}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">Saved connection profiles</p></NxCard><NxCard><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Active endpoints</p><p class="mt-2 text-2xl font-bold">{{activeCount}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">Available to runtime integrations</p></NxCard><NxCard><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Credential handling</p><p class="mt-2 text-lg font-bold">Passwords hidden</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">Blank on edit keeps the current secret</p></NxCard></section><NxToolbar><div class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><label class="grid w-full max-w-md gap-1 text-sm font-semibold">Search servers<input v-model="search" type="search" placeholder="Host, database, or username…" class="min-h-11 rounded-md bg-[var(--nx-surface-muted)] px-4 font-normal"></label><p class="text-sm text-[var(--nx-text-muted)]">{{filtered.length}} of {{rows.length}} servers</p></div></NxToolbar><NxTableShell min-width="820px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase text-[var(--nx-text-muted)]"><tr><th class="px-4 py-3">Host</th><th class="px-4 py-3">Database</th><th class="px-4 py-3">Username</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Updated</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="6" class="px-4 py-12 text-center">{{loading?'Loading RADIUS servers…':'No RADIUS servers found.'}}</td></tr><tr v-for="row in filtered" :key="row.id"><td class="px-4 py-3"><p class="font-mono font-semibold">{{row.host}}</p><p class="text-xs text-[var(--nx-text-muted)]">Connection endpoint</p></td><td class="px-4 py-3">{{row.db_name}}</td><td class="px-4 py-3">{{row.db_user}}</td><td class="px-4 py-3"><NxBadge :tone="Number(row.is_active)?'success':'neutral'">{{Number(row.is_active)?'ACTIVE':'INACTIVE'}}</NxBadge></td><td class="px-4 py-3 text-sm">{{fmt(row.updated_at||row.created_at)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="openEdit(row)">Edit</NxButton><NxButton variant="danger" @click="pendingDelete=row">Delete</NxButton></div></td></tr></tbody></NxTableShell>
<NxModal :open="modalOpen" :title="editing?'Edit RADIUS Server':'Add RADIUS Server'" description="Store the database endpoint in the portal. Passwords are never returned by the API." @close="modalOpen=false"><form @submit.prevent="submit"><NxAlert v-if="modalError" tone="danger" class="mx-6 mt-5">{{modalError}}</NxAlert><div class="grid gap-4 bg-[var(--nx-canvas)] p-6 md:grid-cols-2"><label class="grid gap-1.5 text-sm font-semibold">Host<input v-model="form.host" required placeholder="10.0.10.154" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold">Database name<input v-model="form.db_name" required placeholder="radius" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold">Database username<input v-model="form.db_user" required placeholder="portal_radius" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold">Database password<input v-model="form.db_password" type="password" :required="!editing" autocomplete="new-password" :placeholder="editing?'Leave blank to keep current password':''" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"><span class="text-xs font-normal text-[var(--nx-text-muted)]">{{editing?'Leave blank to keep the current password.':'Required when creating a server.'}}</span></label><label class="flex items-center gap-3 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] p-4 text-sm font-semibold md:col-span-2"><button type="button" role="switch" :aria-checked="Boolean(form.is_active)" class="relative h-6 w-11 rounded-full transition-colors" :class="form.is_active?'bg-brand-600':'bg-slate-400'" @click="form.is_active=form.is_active?0:1"><span class="absolute top-1 size-4 rounded-full bg-white transition-transform" :class="form.is_active?'left-6':'left-1'"></span></button><span><span class="block">Use for runtime RADIUS connections</span><span class="block text-xs font-normal text-[var(--nx-text-muted)]">{{form.is_active?'Endpoint is active':'Endpoint is inactive'}}</span></span></label></div><div class="flex justify-end gap-2 border-t border-[var(--nx-border)] p-5"><NxButton type="button" variant="secondary" @click="modalOpen=false">Cancel</NxButton><NxButton type="submit" :disabled="saving">{{saving?'Saving…':'Save Server'}}</NxButton></div></form></NxModal><NxConfirmDialog :open="Boolean(pendingDelete)" title="Delete RADIUS server?" :description="`The saved connection profile for ${pendingDelete?.host||'this endpoint'} will be permanently removed. Existing subscriber authentication may depend on it.`" confirm-label="Delete Server" danger :busy="saving" :error="modalError" @close="pendingDelete=null" @confirm="executeDelete" /></div></template>
